/// <summary>
/// Base abstract class for OMG data contracts
/// </summary>
abstract class OMGDataContract
{
}

Method.Source:
/// <summary>
/// Ensures that classes extending this overwrites the validate method
/// </summary>
/// <returns>True if all ok</returns>
abstract public boolean validate()
{
}

/// <summary>
/// Returns the class id of the class that should be used for validating the data contract
/// </summary>
/// <returns>The id of that class</returns>
abstract public ClassId validationClassId()
{

}
